// Package server wires the services/api HTTP surface (ADR-0043). Routing +
// ServerInterface are generated by oapi-codegen (gen.go, `task codegen`, config
// oapi-codegen.api.yaml); this file implements that interface. Bodies use the
// internal/resource domain types (the store carries created_at/updated_at not on
// the wire); the generated body models are not used — same rationale as
// audit-service (see oapi-codegen.api.yaml).
//
// Auth posture for the operator-facing SPA (ADR-0047, T-007b):
//
//   - The PASETO session token is set in an HttpOnly cookie by Login and never
//     returned in the response body.  Service-to-service callers continue to
//     send `Authorization: Bearer <paseto>` directly (no cookie).
//   - A non-HttpOnly `aireos_csrf` cookie carries a per-session random value;
//     the SPA reads it via document.cookie and echoes it as `X-CSRF-Token` on
//     every non-GET/HEAD request (double-submit defense).
//   - Sliding refresh: when an operator's verified token has less than half of
//     its TTL remaining, slidingRefresh rotates both cookies inline with the
//     response.  ADR-0046's 8h operator TTL ⇒ refresh window is "< 4h
//     remaining."
//   - `cookieToAuthHeader` is a thin adapter that copies the session cookie
//     into the Authorization header for downstream RequireCapability, keeping
//     `packages/go/middleware/` agnostic of cookie posture (Tech Lead lens).
package server

import (
	"context"
	"crypto/rand"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"github.com/go-chi/chi/v5"

	"aireos.local/packages/go/auth"
	mw "aireos.local/packages/go/middleware"
	"aireos.local/services/api/internal/resource"
	"aireos.local/services/api/internal/session"
	"aireos.local/services/api/internal/store"
)

// Cookie + CSRF contract names (ADR-0047). The SPA in
// packages/shared-types/src/client.ts reads `aireos_csrf` from document.cookie
// and sends the value as the X-CSRF-Token header — change either name here
// and the SPA breaks. The CSRF header name is also the canonical lookup the
// chi-server stub uses on r.Header.Get below.
const (
	sessionCookieName = "aireos_session"
	csrfCookieName    = "aireos_csrf"
	csrfHeaderName    = "X-CSRF-Token"
)

// Store is the narrow slice of *store.Store the handlers need.
type Store interface {
	Create(ctx context.Context, in resource.Input) (resource.Resource, error)
	Get(ctx context.Context, id string) (resource.Resource, error)
	List(ctx context.Context, after string, limit int) ([]resource.Resource, string, error)
	Update(ctx context.Context, id string, in resource.Input) (resource.Resource, error)
	Delete(ctx context.Context, id string) error

	// Cockpit sessions (T-016b). All session reads/writes are operator-scoped:
	// the caller's capability subject is the operator_id, so one operator can
	// never see or end another's sessions (ADR-0048 §5).
	CreateSession(ctx context.Context, operatorID string, in session.CreateInput) (session.Session, error)
	GetSession(ctx context.Context, operatorID, id string) (session.Session, error)
	ListSessions(ctx context.Context, operatorID, after string, limit int) ([]session.Session, string, error)
	EndSession(ctx context.Context, operatorID, id string) (session.Session, error)
}

// Authenticator verifies operator credentials (services/api/internal/account).
type Authenticator interface {
	Authenticate(username, password string) (subject string, ok bool)
}

type apiHandlers struct {
	store  Store
	authn  Authenticator // nil → operator login disabled (503)
	signer *auth.Signer  // nil → operator login disabled (503)
}

// New returns the api router. Routes that declared security in the contract are
// gated by RequireCapability over the human-agent (operator) and service-service
// edges; POST /v1/auth/login (security: []) and POST /v1/auth/logout
// (security: []) are public — see gateByDeclaredSecurity.
//
// Middleware order (effective flow at request time):
//
//	cookieToAuthHeader   — translate aireos_session cookie → Authorization
//	gateByDeclaredSecurity — RequireCapability + CSRF on gated mutations
//	slidingRefresh       — rotate cookies if operator token < half TTL
//
// The slice below is written innermost-first because the generated
// ServerInterfaceWrapper composes middlewares with `handler = m(handler)` per
// iteration — so the LAST entry becomes the outermost wrapper at runtime
// (see gen.go's per-op middleware loop). Reordering this slice without
// understanding that loop will silently break the cookie path.
func New(s Store, authn Authenticator, signer *auth.Signer, v mw.Verifier) http.Handler {
	h := &apiHandlers{store: s, authn: authn, signer: signer}
	return HandlerWithOptions(h, ChiServerOptions{
		BaseRouter: chi.NewRouter(),
		Middlewares: []MiddlewareFunc{
			slidingRefresh(signer),    // innermost  (last to run, closest to handler)
			gateByDeclaredSecurity(v), // middle
			cookieToAuthHeader,        // outermost  (first to run)
		},
	})
}

// cookieToAuthHeader copies aireos_session into the Authorization header when
// Authorization is absent. Service-to-service callers send Authorization
// directly and have no cookie; the SPA sends the cookie and no header. If
// both are present, the existing Authorization wins (no override) — that lets
// admins force a specific bearer for diagnostics.
func cookieToAuthHeader(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Authorization") == "" {
			if c, err := r.Cookie(sessionCookieName); err == nil && c.Value != "" {
				r.Header.Set("Authorization", "Bearer "+c.Value)
			}
		}
		next.ServeHTTP(w, r)
	})
}

// gateByDeclaredSecurity enforces RequireCapability on operations that declared
// security in the contract (the generated wrapper marks them with
// BearerAuthScopes in the request context). It additionally requires a valid
// double-submit CSRF token on mutating requests that authenticated via the
// session cookie. Service-to-service callers (Authorization header, no cookie)
// are exempt from CSRF — there's no browser to defend.
func gateByDeclaredSecurity(v mw.Verifier) MiddlewareFunc {
	require := mw.RequireCapability(v, "human-agent", "service-service")
	return func(next http.Handler) http.Handler {
		afterAuth := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if needsCSRF(r) && !csrfValid(r) {
				writeError(w, http.StatusForbidden, "forbidden", "csrf token missing or mismatched")
				return
			}
			next.ServeHTTP(w, r)
		})
		enforced := require(afterAuth)
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if r.Context().Value(BearerAuthScopes) != nil {
				enforced.ServeHTTP(w, r)
				return
			}
			next.ServeHTTP(w, r)
		})
	}
}

func needsCSRF(r *http.Request) bool {
	switch r.Method {
	case http.MethodGet, http.MethodHead, http.MethodOptions:
		return false
	}
	// Browser path = the request carried a session cookie. Service-service
	// path = Authorization-only, no cookie → no CSRF.
	_, err := r.Cookie(sessionCookieName)
	return err == nil
}

func csrfValid(r *http.Request) bool {
	header := r.Header.Get(csrfHeaderName)
	if header == "" {
		return false
	}
	c, err := r.Cookie(csrfCookieName)
	if err != nil || c.Value == "" {
		return false
	}
	// Constant-time compare via stdlib to avoid byte-by-byte timing oracles on
	// the CSRF value. ConstantTimeCompare returns 0/1, not bool.
	return subtle.ConstantTimeCompare([]byte(header), []byte(c.Value)) == 1
}

// slidingRefresh rotates the session + CSRF cookies inline with the response
// when an operator's token has less than half its TTL remaining (ADR-0047 §6,
// ADR-0046 OperatorTTL = 8h ⇒ refresh window < 4h). Service-service tokens are
// not refreshed (they self-refresh in-process). A nil signer (dev allow-all)
// short-circuits.
func slidingRefresh(signer *auth.Signer) MiddlewareFunc {
	if signer == nil {
		return func(next http.Handler) http.Handler { return next }
	}
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			cap, ok := mw.CapabilityFromContext(r.Context())
			if ok && cap.Edge == "human-agent" && !cap.ExpiresAt.IsZero() {
				remaining := time.Until(cap.ExpiresAt)
				if remaining > 0 && remaining < auth.OperatorTTL/2 {
					if newToken, err := signer.IssueOperator(cap.Subject, cap.Audience); err == nil {
						// Refresh is best-effort: if the cookie write fails
						// (rand failure, header already flushed), continue
						// serving the response — the next request will retry
						// the rotation if still in the refresh window.
						_ = setSessionCookies(w, newToken)
					}
				}
			}
			next.ServeHTTP(w, r)
		})
	}
}

// setSessionCookies writes the session + CSRF cookies on a successful login
// or a sliding refresh. Cookie attributes are ADR-0047 §Decision:
//   - HttpOnly on the session cookie (PASETO opaque to JS by construction).
//   - SameSite=Strict on both (primary CSRF defense; double-submit is layered).
//   - Secure on both (HTTPS-only; modern browsers treat localhost as secure).
//   - Path=/ so both apply to every SPA / API path under the same origin.
//   - MaxAge = OperatorTTL seconds.
func setSessionCookies(w http.ResponseWriter, token string) error {
	csrf, err := newCSRFToken()
	if err != nil {
		return err
	}
	maxAge := int(auth.OperatorTTL / time.Second)
	http.SetCookie(w, &http.Cookie{
		Name:     sessionCookieName,
		Value:    token,
		Path:     "/",
		MaxAge:   maxAge,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
	})
	http.SetCookie(w, &http.Cookie{
		Name:     csrfCookieName,
		Value:    csrf,
		Path:     "/",
		MaxAge:   maxAge,
		HttpOnly: false, // SPA reads this to echo X-CSRF-Token.
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
	})
	return nil
}

func clearSessionCookies(w http.ResponseWriter) {
	for _, name := range []string{sessionCookieName, csrfCookieName} {
		http.SetCookie(w, &http.Cookie{
			Name:     name,
			Value:    "",
			Path:     "/",
			MaxAge:   -1, // delete
			HttpOnly: name == sessionCookieName,
			Secure:   true,
			SameSite: http.SameSiteStrictMode,
		})
	}
}

func newCSRFToken() (string, error) {
	var b [32]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	return hex.EncodeToString(b[:]), nil
}

// Login (POST /v1/auth/login) verifies operator credentials and establishes
// the session by setting an HttpOnly session cookie + a non-HttpOnly CSRF
// cookie (ADR-0046, ADR-0047). The PASETO token is NOT returned in the body —
// it stays opaque to JS by construction. Public route.
func (a *apiHandlers) Login(w http.ResponseWriter, r *http.Request) {
	if a.authn == nil || a.signer == nil {
		writeError(w, http.StatusServiceUnavailable, "unavailable", "operator login is not configured")
		return
	}
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := dec.Decode(&req); err != nil || req.Username == "" || req.Password == "" {
		writeError(w, http.StatusBadRequest, "bad_request", "username and password are required")
		return
	}
	subject, ok := a.authn.Authenticate(req.Username, req.Password)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "invalid credentials")
		return
	}
	// Operator tokens are scoped to this gateway's audience ("api").
	token, err := a.signer.IssueOperator(subject, "api")
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "issue token failed")
		return
	}
	if err := setSessionCookies(w, token); err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "set cookies failed")
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{
		"expiresAt": time.Now().Add(auth.OperatorTTL).UTC().Format(time.RFC3339),
	})
}

// Logout (POST /v1/auth/logout) clears the session + CSRF cookies. Public:
// callers with stale/expired cookies can recover. SameSite=Strict on the
// session cookie blocks cross-site CSRF on this endpoint at the browser layer.
func (a *apiHandlers) Logout(w http.ResponseWriter, _ *http.Request) {
	clearSessionCookies(w)
	w.WriteHeader(http.StatusNoContent)
}

// GetMe (GET /v1/auth/me) returns the verified capability of the current token.
func (a *apiHandlers) GetMe(w http.ResponseWriter, r *http.Request) {
	c, ok := mw.CapabilityFromContext(r.Context())
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"subject": c.Subject, "edge": c.Edge})
}

func (a *apiHandlers) decodeInput(w http.ResponseWriter, r *http.Request) (resource.Input, bool) {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields() // rejects a client-supplied id with 400
	var in resource.Input
	if err := dec.Decode(&in); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "invalid request body: "+err.Error())
		return resource.Input{}, false
	}
	if err := in.Validate(); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", err.Error())
		return resource.Input{}, false
	}
	return in, true
}

func (a *apiHandlers) CreateResource(w http.ResponseWriter, r *http.Request) {
	in, ok := a.decodeInput(w, r)
	if !ok {
		return
	}
	res, err := a.store.Create(r.Context(), in)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "create failed")
		return
	}
	writeJSON(w, http.StatusCreated, res)
}

type resourcePage struct {
	Items []resource.Resource `json:"items"`
	Page  pageMeta            `json:"page"`
}

type pageMeta struct {
	NextCursor string `json:"nextCursor,omitempty"`
}

func (a *apiHandlers) ListResources(w http.ResponseWriter, r *http.Request, params ListResourcesParams) {
	limit := 50
	if params.Limit != nil {
		n := int(*params.Limit)
		if n < 1 || n > 200 {
			writeError(w, http.StatusBadRequest, "bad_request", "limit must be an integer in [1,200]")
			return
		}
		limit = n
	}
	var after string
	if params.Cursor != nil {
		after = string(*params.Cursor)
	}
	items, last, err := a.store.List(r.Context(), after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "list failed")
		return
	}
	page := resourcePage{Items: items}
	if len(items) == limit {
		page.Page.NextCursor = last
	}
	writeJSON(w, http.StatusOK, page)
}

func (a *apiHandlers) GetResource(w http.ResponseWriter, r *http.Request, id string) {
	res, err := a.store.Get(r.Context(), id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "get failed")
		return
	}
	writeJSON(w, http.StatusOK, res)
}

func (a *apiHandlers) UpdateResource(w http.ResponseWriter, r *http.Request, id string) {
	in, ok := a.decodeInput(w, r)
	if !ok {
		return
	}
	res, err := a.store.Update(r.Context(), id, in)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "update failed")
		return
	}
	writeJSON(w, http.StatusOK, res)
}

func (a *apiHandlers) DeleteResource(w http.ResponseWriter, r *http.Request, id string) {
	err := a.store.Delete(r.Context(), id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "delete failed")
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// operatorSubject pulls the verified capability subject out of the request
// context (populated by RequireCapability). It is the session owner key. A
// missing capability on a gated route should be impossible — the gate runs
// first — but we fail closed with 401 rather than minting sessions under an
// empty operator id.
func operatorSubject(r *http.Request) (string, bool) {
	c, ok := mw.CapabilityFromContext(r.Context())
	if !ok || c.Subject == "" {
		return "", false
	}
	return c.Subject, true
}

// CreateSession (POST /v1/sessions) records the operator's intent to start a
// session against a resource. The row is created 'pending'; the broker activates
// it on a successful PTY attach (slice b). A SessionCreate body referencing an
// unknown resourceId answers 404 (FK → ErrNotFound).
func (a *apiHandlers) CreateSession(w http.ResponseWriter, r *http.Request) {
	operator, ok := operatorSubject(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields() // rejects a client-supplied id/status/operatorId with 400
	var in session.CreateInput
	if err := dec.Decode(&in); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "invalid request body: "+err.Error())
		return
	}
	in.Normalize()
	if err := in.Validate(); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", err.Error())
		return
	}
	sess, err := a.store.CreateSession(r.Context(), operator, in)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "resource not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "create session failed")
		return
	}
	writeJSON(w, http.StatusCreated, sess)
}

type sessionPage struct {
	Items []session.Session `json:"items"`
	Page  pageMeta          `json:"page"`
}

// ListSessions (GET /v1/sessions) returns a page of the caller's own sessions
// (operator-scoped; no cross-operator scope at v0.1.0).
func (a *apiHandlers) ListSessions(w http.ResponseWriter, r *http.Request, params ListSessionsParams) {
	operator, ok := operatorSubject(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	limit := 50
	if params.Limit != nil {
		n := int(*params.Limit)
		if n < 1 || n > 200 {
			writeError(w, http.StatusBadRequest, "bad_request", "limit must be an integer in [1,200]")
			return
		}
		limit = n
	}
	var after string
	if params.Cursor != nil {
		after = string(*params.Cursor)
	}
	items, last, err := a.store.ListSessions(r.Context(), operator, after, limit)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "list sessions failed")
		return
	}
	page := sessionPage{Items: items}
	if len(items) == limit {
		page.Page.NextCursor = last
	}
	writeJSON(w, http.StatusOK, page)
}

// GetSession (GET /v1/sessions/{id}) returns session metadata the caller owns.
func (a *apiHandlers) GetSession(w http.ResponseWriter, r *http.Request, id string) {
	operator, ok := operatorSubject(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	sess, err := a.store.GetSession(r.Context(), operator, id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "session not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "get session failed")
		return
	}
	writeJSON(w, http.StatusOK, sess)
}

// EndSession (POST /v1/sessions/{id}/end) records the operator's intent to end a
// session. The transition is idempotent; the broker performs the real teardown
// and emits session.close (slice b).
func (a *apiHandlers) EndSession(w http.ResponseWriter, r *http.Request, id string) {
	operator, ok := operatorSubject(r)
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "no capability")
		return
	}
	sess, err := a.store.EndSession(r.Context(), operator, id)
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "not_found", "session not found")
		return
	}
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal", "end session failed")
		return
	}
	writeJSON(w, http.StatusOK, sess)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, message string) {
	writeJSON(w, status, map[string]string{"code": code, "message": message})
}
